using System;using System.Collections;using System.Collections.Generic;using EntryPoint.EntryPoints;using Game.GamePlay.Root;using UnityEngine;using UnityEngine.Events;public class ActionSystem : MonoBehaviour {    [SerializeField] private Camera maincam;    [SerializeField] private GameObject cursor;    [SerializeField] private AudioSource pickUpSound;    [SerializeField] private int distance;        private ResultActions resultActions;    public IEnumerator<ActionSystem> Init(ResultActions resultActions) {        this.resultActions = resultActions;                yield return this;    }        private void Update() {         if(!GameplayEntryPoint.isSceneLoaded) return;                if (Physics.Raycast(maincam.transform.position, maincam.transform.forward, out var hit, distance)) {            if (hit.collider.CompareTag("action")) {                cursor.SetActive(true);                                if (Input.GetKeyDown(KeyCode.E)){                                        hit.collider.GetComponent<IAction>().StartAction(error => {                        resultActions.StopAllCoroutines();                        if (error == Results.IndexIsTaken)                             StartCoroutine(resultActions.IndexIsTaken());                                                if (error == Results.HasNoItem)                             StartCoroutine(resultActions.HasNoItem());                        if (error == Results.MachineIsOn)                            StartCoroutine(resultActions.MachineIsOn());                                                if(error == Results.Success)                            pickUpSound.Play();                                                Debug.Log(error);                    });                }            } else                cursor.SetActive(false);            if (hit.collider.CompareTag("LookEvent")) { // getting an event object to start an event                EventObject eventObject = hit.collider.GetComponent<EventObject>();                if(eventObject.EndingType == EventEndingTypes.ByLook)                    hit.collider.GetComponent<IAction>().StartAction(null);            }                                } else            cursor.SetActive(false);    }    }